description:
Implement `useVirtualizedList` for efficiently rendering large lists where every item has the same fixed height. Only the items visible in the container (plus a small overscan) should be returned.

**Example:**
```tsx
const items = Array.from({ length: 10000 }, (_, i) => `Item ${i}`);

function VirtualList() {
  const { virtualItems, totalHeight, onScroll } = useVirtualizedList({
    items,
    itemHeight: 40,
    containerHeight: 400,
  });

  return (
    <div style={{ height: 400, overflow: 'auto' }} onScroll={onScroll}>
      <div style={{ height: totalHeight, position: 'relative' }}>
        {virtualItems.map(({ index, item, offsetY }) => (
          <div key={index} style={{ position: 'absolute', top: offsetY, height: 40 }}>
            {item}
          </div>
        ))}
      </div>
    </div>
  );
}
```

