solution:
import { useState, useCallback } from 'react';

type VirtualItem<T> = { index: number; item: T; offsetY: number };

type UseVirtualizedListOptions<T> = {
  items: T[];
  itemHeight: number;
  containerHeight: number;
};

export function useVirtualizedList<T>({
  items,
  itemHeight,
  containerHeight,
}: UseVirtualizedListOptions<T>) {
  const [scrollTop, setScrollTop] = useState(0);
  const overscan = 3;

  const totalHeight = items.length * itemHeight;
  const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - overscan);
  const visibleCount = Math.ceil(containerHeight / itemHeight) + overscan * 2;
  const endIndex = Math.min(items.length - 1, startIndex + visibleCount);

  const virtualItems: VirtualItem<T>[] = [];
  for (let i = startIndex; i <= endIndex; i++) {
    virtualItems.push({ index: i, item: items[i], offsetY: i * itemHeight });
  }

  const onScroll = useCallback((e: React.UIEvent<HTMLElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  return { virtualItems, totalHeight, onScroll };
}
